export type PriceListEntry = { insuranceValue: number; basePremium: number };

const MAIN_ITEM_PRICES: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
export const COMPONENT_TYPES = ["rune", "moonstone"];
export const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };

export function priceListEntry(itemType: string): PriceListEntry {
  const entry = COMPONENT_TYPES.includes(itemType) ? COMPONENT_PRICE : MAIN_ITEM_PRICES[itemType];
  if (entry === undefined) {
    throw new Error(`Unknown item type: ${itemType}`);
  }
  return entry;
}
import type { Damage, Item } from "./claimOffice.js";
import { priceListEntry } from "./priceList.js";

const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;

export type Policy = { remainingCap: number };
export type ClaimSettlement = { payout: number; remainingCap: number };

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceListEntry(item.type).insuranceValue, 0);
}

export function insureItems(items: Item[]): Policy {
  return { remainingCap: insuranceSum(items) * CAP_MULTIPLIER };
}

function damageEventPayout(damage: Damage): number {
  return damage.amount - DEDUCTIBLE;
}

export function processClaim(policy: Policy, damages: Damage[]): ClaimSettlement {
  const payout = damages.reduce((sum, damage) => sum + damageEventPayout(damage), 0);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

