import type { Damage, Item } from "./claimOffice.js";
import { damageEventPayout } from "./damageReimbursement.js";
import { roundPayoutInMhpcoFavor } from "./mhpcoRounding.js";
import type { Policy } from "./policyCoverage.js";

export type ClaimSettlement = { payout: number; remainingCap: number };

function damagedInsuredItem(policy: Policy, damage: Damage): Item | undefined {
  return policy.items.find((item) => item.type === damage.itemType);
}

function incidentPayout(policy: Policy, damages: Damage[]): number {
  return roundPayoutInMhpcoFavor(
    damages.reduce((sum, damage) => sum + damageEventPayout(damage, damagedInsuredItem(policy, damage)), 0),
  );
}

export function processClaim(policy: Policy, damages: Damage[]): ClaimSettlement {
  const payout = incidentPayout(policy, damages);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

